using System;using System.Text.Json;using Exoduser.UnityPort.Core;using Exoduser.UnityPort.Core.Combat;
class Program {
 static int total,failed;static void Check(bool b,string name){total++;if(!b){failed++;Console.WriteLine("FAIL "+name);}}
 static Simulation Sim(){var s=new Simulation(new SimulationConfig{PlayerMaxHp=1000,PlayerMaxStamina=1000,PlayerMaxMana=1000,PlayerPhysicalDefense=0,PlayerEnergyDefense=0,DamageMultiplier=1,PlayerHpRegen=0,PlayerManaRegen=0,PlayerStaminaRegen=0});s.Random01=()=>.5;return s;}
 static EnemyState Enemy(Simulation s,int et=0){var e=s.SpawnEnemy(30,0,et);e.Elite=0;e.Web.mods.Clear();e.Hp=e.MaxHp=10000;e.Poise=e.MaxPoise=1000;e.Attack=e.BaseAttack=31;e.Shield=e.MaxShield=0;e.Speed=0;e.Alerted=true;e.StateTicks=0;e.Web.MeleeCooldown=0;return e;}
 static void Step(Simulation s,int count=1){for(int i=0;i<count;i++)s.Tick(0,0,100,0,false,false);}
 static int Main(){
  var s=Sim();s.Player.Hp=s.Player.Stamina=s.Player.Mana=1;s.HarpGauge=0;s.PayReflectParry(new ParryReflect.ResolveResult{ResourceMul=1});Check(s.Player.Hp==17&&s.Player.Stamina==17&&s.Player.Mana==17,"projectile recovery truncates once");Check(s.HarpGauge==10&&s.Rage==10&&s.Materials==1000,"projectile economy half");Check(s.Player.Poise==4&&s.Player.Iframes==25,"projectile poise and invulnerability unchanged");var fx=s.Feedback.Dequeue();Check(!fx.MeleeParry&&fx.HitStopTicks==0&&fx.ParryShake==4,"projectile feedback");
  foreach(int mul in new[]{1,3,10})foreach(string el in new[]{"red","rainbow","normal"}){var i=new ParryRewards.Input{Kind=ParryKind.Projectile,Hp=0,Mhp=10000,St=0,Mst=10000,Mp=0,Mmp=10000,ResourceMul=mul,ParryEl=el,OptHitStop=100,OptShake=100};var r=ParryRewards.Apply(i);Check(r.Hp==(int)(50.0/3*(el=="red"?.5:el=="rainbow"?1.5:1)*mul),"resource multiplier after divisor "+el+mul);Check(r.HitStop==0&&r.SlowMo==0,"projectile tempo");}
  s=Sim();var e=Enemy(s);s.Player.Hp=1;s.Player.State="sBash";s.Player.StateTicks=20;s.HurtPlayer(31,new HurtOptions{MeleeEnemy=e,MeleeSource="swing",Source="meleeEnemy"});Check(s.ParryCount==1&&s.Player.Hp==51&&s.ParryBank==31,"melee E rewards and bank");Check(e.Poise==700&&e.MeleeCounterUntil==36&&e.MeleeFreezeUntil==36,"normal poise 30 percent and 36 tick counter");Check(s.Stats.parrySuccess["meleeE"]==1&&s.Stats.meleeGain["hp"]==50,"melee stats");Check(Math.Abs(s.Stats.meleeGain["hpMaxFrac"]-50.0/s.Player.MaxHp)<1e-9&&s.Stats.projGain["hpMaxFrac"]==0,"melee hp gain as max HP fraction");fx=s.Feedback.Dequeue();Check(fx.MeleeParry&&fx.HitStopTicks==2&&fx.ParryShake==6,"melee tempo");float x=e.X;s.Player.State="idle";Step(s,10);Check(e.X==x&&e.Web.MeleeTimer==0,"freeze no movement or attack");s.HurtEnemy(e,40);Check(e.Hp==9930&&e.Poise==560,"first counter damage 1.75 poise twice");Check(e.MeleeCounterUntil==s.TickCount&&e.MeleeFreezeUntil==36,"counter consumed independently of freeze");s.HurtEnemy(e,40);Check(e.Hp==9890,"second hit normal");Check(s.Stats.dmgDealt["counter"]==70,"counter damage source");
  foreach(int et in new[]{0,4,6,19,29}){s=Sim();e=Enemy(s,et);s.Player.State="sBlock";s.SbParryT=20;s.HurtPlayer(31,new HurtOptions{MeleeEnemy=e,MeleeSource="combo",Source="meleeEnemy"});Check(s.Stats.parrySuccess["meleeQ"]==1,"Q melee "+et);Check(e.MeleeCounterUntil==MeleeAttackRules.CounterTicks(et),"counter duration "+et);Check(e.Poise==(et==29?800:700),"gate poise fraction "+et);}
  s=Sim();e=Enemy(s);s.Player.State="sBash";s.Player.StateTicks=20;s.Random01=()=>0;s.DodgeAffix=1;s.HurtPlayer(31,new HurtOptions{MeleeEnemy=e});Check(s.DodgeCount==1&&s.ParryCount==0&&e.Poise==1000,"dodge precedes parry");
  foreach(bool q in new[]{false,true}){s=Sim();e=Enemy(s);s.Player.State=q?"sBlock":"sBash";s.Player.StateTicks=20;s.SbParryT=q?20:0;s.HurtPlayer(31,new HurtOptions{MeleeEnemy=e,Unparryable=true,Source="meleeEnemy"});Check(s.ParryCount==0&&s.HurtCount==1&&s.Stats.parryWrongInput==1,"DANGER E/Q takes ordinary hit");}
  foreach(int et in new[]{0,4,6,19,29}){s=Sim();e=Enemy(s,et);Step(s);int tell=et==0?24:et==4?36:et==6?24:et==19?18:30;Check(e.Web.s=="g2Tell"&&e.Web.MeleeTimer==tell,"tell start "+et);Step(s,tell-1);Check(s.HurtCount==0&&e.Web.s=="g2Tell","no early contact "+et);Step(s);Check(e.Web.s=="g2Active"&&s.HurtCount==0,"active boundary "+et);Step(s);Check(s.HurtCount==1,"first active frame damage "+et);Check(e.Web.projCd>=9000,"target generic projectile disabled "+et);}
  Check(EnemyProjectilePolicy.Interval(10)==480&&EnemyProjectilePolicy.Interval(1)==240&&EnemyProjectilePolicy.Interval(9)==9999,"shared projectile pool policy");
  s=Sim();e=Enemy(s);e.Poise=250;s.Player.State="sBash";s.Player.StateTicks=20;s.HurtPlayer(31,new HurtOptions{MeleeEnemy=e});Check(s.Stats.groggy["meleeParry"]==1,"melee groggy cause");using(var json=JsonDocument.Parse(s.CombatStatsJson()))Check(json.RootElement.GetProperty("groggy").GetProperty("meleeParry").GetDouble()==1,"combat stats JSON");
  foreach(int et in new[]{19,29}){s=Sim();e=Enemy(s,et);Step(s);Step(s,et==19?18:30);s.Player.State="sBash";s.Player.StateTicks=20;Step(s);Check(s.ParryCount==1&&e.Web.s=="idle","parry cancels combo "+et);s.Player.State="idle";Step(s,20);Check(s.Stats.meleeTellStarted["unparryable"]==0,"no forbidden followup during counter "+et);}
  s=Sim();e=Enemy(s);var bot=new ParryRhythmBot();int decisions=0;for(int k=1;k<=10;k++){e.Web.s="g2Tell";e.Web.MeleeTimer=6;e.Web.MeleeTellSerial=k;if(bot.Input(s)==1)decisions++;}Check(decisions==7&&bot.opportunities==10,"bot seven of ten tell signals");
  s=Sim();e=Enemy(s);s.ParryFeedback.meleeShake=2;s.ParryFeedback.meleeCameraPushIn=.08f;s.Player.State="sBash";s.Player.StateTicks=20;s.HurtPlayer(31,new HurtOptions{MeleeEnemy=e});fx=s.Feedback.Dequeue();Check(fx.ParryShake==2&&fx.CameraPushIn==.08f,"configurable push in and shake");
  s=Sim();e=Enemy(s);s.Player.State="sBash";s.Player.StateTicks=20;s.HurtPlayer(31,new HurtOptions{MeleeEnemy=e});s.PayReflectParry(new ParryReflect.ResolveResult{ResourceMul=1});Check(s.Stats.parrySuccess["meleeE"]==1&&s.Stats.parrySuccess["projE"]==1,"kind counters independent");
  s=Sim();e=Enemy(s);s.Player.State="sBash";s.Player.StateTicks=20;s.HurtPlayer(31,new HurtOptions{MeleeEnemy=e});s.Player.State="idle";e.Web.bleed=1;e.Web.bleedT=61;e.Web._bleedPool=60;Step(s,2);Check(e.Hp<10000&&e.MeleeCounterUntil==36,"DOT continues during freeze without consuming counter");
  int noProjDraws=0;var noProj=EnemyFactory.Create(new EnemySpawnContext{PlayerLevel=100,DifficultyIndex=5,Stage=0,CanMove=(a,b,c)=>true,Random=()=>noProjDraws++==0?.01:.5},0,0,0,50,false,1,null);Check(noProj.elite==1&&noProj.projCd==7999,"non-target NoProj preserves elite cooldown");
  Console.WriteLine(total+" checks / "+failed+" failures");return failed==0?0:1;
 }
}
